fn get_array_type(btype: &BType, shape: &[usize]) -> TypeKind {
    if shape.is_empty() {
        return btype.content.clone();
    }
    let inner_typekind = get_array_type(btype, &shape[1..]);
    TypeKind::Array(Type::get(inner_typekind), shape[0])
}

