/// match the given argument types.
fn check_bb_arg_types(querier: &impl EntityInfoQuerier, params: &[Value], args: &[Value]) {
  assert!(
    params.len() == args.len()
      && params
        .iter()
        .zip(args.iter())
        .all(|(p, a)| querier.value_type(*p) == querier.value_type(*a)),
